-- The PostgreSQL baseline (v3 Phase 1C slice 2, docs/adr/0007): the same schema as a SQLite database after
-- agent-core:001-runs and health-review:001 to 033 (db/migrate.js, db/migrations.js, db/migrations-users.js). Columns
-- keep SQLite's order, since SELECT * returns them in that order. Types map one for one:
--   INTEGER       bigint (SQLite integers are 64 bit; the pool parses int8 as numbers, db/postgres.ts)
--   INTEGER PRIMARY KEY (a rowid alias)   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
--   REAL          double precision
--   TEXT          text; TEXT COLLATE NOCASE is citext, which folds ASCII case like NOCASE on a C-ctype database
-- Keys, uniques, foreign keys, checks and indexes are the same. test/schema-parity.test.js compares the two, so a
-- later SQLite migration needs its PostgreSQL twin in db/pg/migrations.js under the same id.

CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE users (
  id text PRIMARY KEY,
  email text NOT NULL UNIQUE,
  name text,
  role text NOT NULL CHECK (role IN ('admin', 'user')),
  status text NOT NULL CHECK (status IN ('pending', 'approved', 'rejected', 'paused')),
  created_at text NOT NULL,
  approved_at text,
  last_seen_at text,
  claude_key_enc text,
  claude_key_set_at text,
  terms_accepted_at text,
  uses_owner_key bigint NOT NULL DEFAULT 0 CHECK (uses_owner_key IN (0, 1)),
  owner_key_cap_usd double precision,
  ingest_token_hash text,
  feeds text,
  maps_shared bigint NOT NULL DEFAULT 0 CHECK (maps_shared IN (0, 1)),
  google_refresh_enc text,
  google_connected_at text,
  health_consent_at text,
  health_consent_version text
);

CREATE TABLE runs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  meta text,
  status text NOT NULL DEFAULT 'running',
  started_at text NOT NULL,
  finished_at text,
  duration_ms bigint,
  calls bigint NOT NULL DEFAULT 0,
  errors bigint NOT NULL DEFAULT 0,
  input_tokens bigint NOT NULL DEFAULT 0,
  output_tokens bigint NOT NULL DEFAULT 0,
  cache_read_tokens bigint NOT NULL DEFAULT 0,
  cache_write_tokens bigint NOT NULL DEFAULT 0,
  cost_usd double precision,
  summary text,
  user_id text REFERENCES users(id)
);

CREATE TABLE run_calls (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id bigint NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  label text,
  model text,
  stop_reason text,
  input_tokens bigint NOT NULL DEFAULT 0,
  output_tokens bigint NOT NULL DEFAULT 0,
  cache_read_tokens bigint NOT NULL DEFAULT 0,
  cache_write_tokens bigint NOT NULL DEFAULT 0,
  cost_usd double precision,
  duration_ms bigint,
  error_name text,
  error_message text,
  created_at text NOT NULL
);

CREATE TABLE daily_metrics (
  user_id text NOT NULL REFERENCES users(id),
  date text NOT NULL,
  active_energy_kcal double precision, exercise_min double precision, move_min double precision,
  stand_hours double precision, stand_min double precision, hrv_ms double precision,
  respiratory_rate double precision, resting_hr double precision, sleep_total_hr double precision,
  sleep_asleep_hr double precision, sleep_in_bed_hr double precision, sleep_core_hr double precision,
  sleep_deep_hr double precision, sleep_rem_hr double precision, sleep_awake_hr double precision,
  steps double precision, vo2max double precision,
  updated_at text NOT NULL,
  cardio_recovery_bpm double precision, walking_hr_avg double precision, walking_speed_mph double precision,
  hr_min double precision, hr_max double precision, hr_avg double precision, wrist_temp_f double precision,
  physical_effort double precision, spo2_pct double precision, breathing_disturbances double precision,
  walking_asymmetry_pct double precision,
  exported_through text,
  PRIMARY KEY (user_id, date)
);

CREATE TABLE workout_sessions (
  user_id text NOT NULL REFERENCES users(id),
  type text NOT NULL, start text NOT NULL, "end" text NOT NULL,
  duration_sec bigint, total_energy_kcal double precision, active_energy_kcal double precision,
  max_hr double precision, avg_hr double precision, distance_mi double precision, avg_speed_mph double precision,
  step_count double precision, step_cadence_spm double precision, swim_stroke_count double precision,
  swim_stroke_cadence_spm double precision, flights_climbed double precision, elevation_up_ft double precision,
  elevation_down_ft double precision,
  updated_at text NOT NULL,
  PRIMARY KEY (user_id, type, start, "end")
);

CREATE TABLE workout_hr_samples (
  user_id text NOT NULL REFERENCES users(id),
  type text NOT NULL, start text NOT NULL, t text NOT NULL,
  avg_bpm double precision NOT NULL, min_bpm double precision, max_bpm double precision,
  PRIMARY KEY (user_id, type, start, t)
);

CREATE TABLE stand_hour_samples (
  user_id text NOT NULL REFERENCES users(id),
  date text NOT NULL,
  hour bigint NOT NULL CHECK (hour BETWEEN 0 AND 23),
  PRIMARY KEY (user_id, date, hour)
);

CREATE TABLE strength_exercises (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  tab_year bigint NOT NULL, row_no bigint NOT NULL, date text NOT NULL,
  workout text, prime text, exercise text NOT NULL, post text, comment text,
  canonical_id text, implement text, movement_pattern text,
  is_primary bigint NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  map_status text NOT NULL DEFAULT 'pending' CHECK (map_status IN ('pending', 'mapped', 'inferred', 'unmapped', 'ignored')),
  normalized_at text,
  UNIQUE (user_id, tab_year, row_no)
);

CREATE TABLE strength_sets (
  user_id text NOT NULL REFERENCES users(id),
  exercise_id bigint NOT NULL REFERENCES strength_exercises(id) ON DELETE CASCADE,
  set_no bigint NOT NULL,
  weight_text text, weight_lbs double precision, per_hand bigint NOT NULL DEFAULT 0, band text,
  bodyweight bigint NOT NULL DEFAULT 0, reps_text text, reps bigint, duration_sec bigint, distance_yd double precision,
  PRIMARY KEY (exercise_id, set_no)
);

CREATE TABLE workout_log_notes (
  user_id text NOT NULL REFERENCES users(id),
  tab_year bigint NOT NULL, row_no bigint NOT NULL, date text, text text NOT NULL,
  PRIMARY KEY (user_id, tab_year, row_no)
);

CREATE TABLE sync_state (
  user_id text NOT NULL REFERENCES users(id),
  source text NOT NULL, tab text NOT NULL, row_count bigint NOT NULL,
  header_hash text, content_hash text, synced_at text NOT NULL,
  PRIMARY KEY (user_id, source, tab)
);

CREATE TABLE drive_exports (
  user_id text NOT NULL REFERENCES users(id),
  file_id text PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('health', 'health_json', 'workouts')),
  name text NOT NULL, modified_time text NOT NULL, rows bigint NOT NULL, synced_at text NOT NULL
);

CREATE TABLE ingest_log (
  id text PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  received_at text NOT NULL,
  route text NOT NULL CHECK (route IN ('health', 'workouts')),
  result text NOT NULL CHECK (result IN ('ok', 'error')),
  counts text, error text
);

CREATE TABLE checkins (
  user_id text NOT NULL REFERENCES users(id),
  date text NOT NULL,
  cadence text NOT NULL CHECK (cadence IN ('weekly', 'daily')),
  readiness bigint, energy bigint, mood bigint, stress bigint, nutrition bigint,
  weight_lbs double precision, body_fat_pct double precision, muscle_mass_lbs double precision,
  visceral_fat double precision, body_measured_on text,
  notes text, source text NOT NULL, updated_at text NOT NULL,
  PRIMARY KEY (user_id, date)
);

CREATE TABLE drinking_days (
  user_id text NOT NULL REFERENCES users(id),
  date text NOT NULL,
  beers bigint NOT NULL DEFAULT 0, wine bigint NOT NULL DEFAULT 0, bourbon bigint NOT NULL DEFAULT 0,
  other bigint NOT NULL DEFAULT 0, setting text, mood_before bigint, mood_after bigint, notes text,
  source text NOT NULL, updated_at text NOT NULL, cbd bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, date)
);

CREATE TABLE settings (
  user_id text NOT NULL REFERENCES users(id),
  key text NOT NULL, value text NOT NULL, updated_at text NOT NULL,
  PRIMARY KEY (user_id, key)
);

CREATE TABLE health_targets (
  user_id text NOT NULL REFERENCES users(id),
  metric text NOT NULL, target double precision NOT NULL, updated_at text NOT NULL,
  PRIMARY KEY (user_id, metric)
);

CREATE TABLE reviews (
  user_id text NOT NULL REFERENCES users(id),
  week_ending text NOT NULL,
  summary_json text NOT NULL, report_md text NOT NULL, run_id bigint, created_at text NOT NULL,
  model text, warnings text, sensitive_sections text,
  PRIMARY KEY (user_id, week_ending)
);

CREATE TABLE prompt_sections (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  position bigint NOT NULL, name text NOT NULL, text text NOT NULL,
  sensitive bigint NOT NULL DEFAULT 0, updated_at text NOT NULL,
  UNIQUE (user_id, name)
);

CREATE TABLE prompt_section_versions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  section_id bigint NOT NULL, position bigint NOT NULL, name text NOT NULL, text text NOT NULL,
  sensitive bigint NOT NULL, replaced_at text NOT NULL
);

CREATE TABLE advisor_notes (
  id text PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  created_at text NOT NULL,
  role text NOT NULL CHECK (role IN ('owner', 'claude')),
  text text NOT NULL, physician text, weights text, model text, warnings text
);

CREATE TABLE program_blocks (
  id text PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  program text NOT NULL, phase text, start_date text NOT NULL, end_date text,
  status text NOT NULL CHECK (status IN ('completed', 'abandoned', 'in_progress')),
  source text NOT NULL CHECK (source IN ('detected', 'confirmed')),
  notes text, created_at text NOT NULL, updated_at text NOT NULL, program_weeks bigint
);

CREATE TABLE log_sessions (
  id text PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  date text NOT NULL,
  block_id text REFERENCES program_blocks(id) ON DELETE SET NULL,
  assignment text NOT NULL CHECK (assignment IN ('block', 'unassigned')),
  program text, week bigint,
  source text NOT NULL CHECK (source IN ('detected', 'confirmed', 'forward')),
  updated_at text NOT NULL, phase text,
  UNIQUE (user_id, date)
);

CREATE TABLE medications (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  name citext NOT NULL,
  kind text NOT NULL CHECK (kind IN ('medication', 'supplement')),
  purpose text, prescribed bigint NOT NULL DEFAULT 0, created_at text NOT NULL, notes text,
  UNIQUE (user_id, name)
);

CREATE TABLE medication_periods (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  medication_id bigint NOT NULL REFERENCES medications(id) ON DELETE CASCADE,
  dose text,
  timings text NOT NULL, -- JSON array of morning, afternoon, before_bed, before_workout, after_workout, daily
  started_on text NOT NULL, stopped_on text, stop_reason text, created_at text NOT NULL,
  start_estimated bigint NOT NULL DEFAULT 0, ingredients text,
  CHECK (stopped_on IS NULL OR stopped_on >= started_on)
);

CREATE TABLE medication_doses (
  user_id text NOT NULL REFERENCES users(id),
  date text NOT NULL,
  medication_id bigint NOT NULL REFERENCES medications(id) ON DELETE CASCADE,
  timing text NOT NULL,
  taken bigint NOT NULL CHECK (taken IN (0, 1)),
  updated_at text NOT NULL, dose text, moved_to text,
  PRIMARY KEY (date, medication_id, timing)
);

CREATE TABLE lab_tests (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  name citext NOT NULL,
  panel text, unit text, position bigint NOT NULL DEFAULT 9999, created_at text NOT NULL,
  ref_low double precision, ref_high double precision, ref_set bigint NOT NULL DEFAULT 0,
  UNIQUE (user_id, name)
);

CREATE TABLE lab_results (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  test_id bigint NOT NULL REFERENCES lab_tests(id) ON DELETE CASCADE,
  drawn_on text NOT NULL, value double precision, value_text text NOT NULL,
  source text NOT NULL CHECK (source IN ('sheet', 'ui')),
  updated_at text NOT NULL, corrected_from text, corrected_from_date text,
  UNIQUE (test_id, drawn_on)
);

CREATE TABLE user_programs (
  id text PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  name text NOT NULL,
  match text NOT NULL,
  program text NOT NULL,
  source text NOT NULL CHECK (source IN ('manual', 'import', 'pdf')),
  created_at text NOT NULL,
  updated_at text NOT NULL,
  UNIQUE (user_id, name)
);

CREATE TABLE feedback (
  id text PRIMARY KEY,
  user_id text NOT NULL REFERENCES users(id),
  kind text NOT NULL CHECK (kind IN ('feedback', 'enhancement', 'bug')),
  subject text NOT NULL,
  body text NOT NULL,
  context text,
  status text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'done')),
  created_at text NOT NULL
);

CREATE TABLE usage_totals (
  day text NOT NULL,
  dimension text NOT NULL CHECK (dimension IN ('device', 'browser', 'location', 'source')),
  value text NOT NULL,
  count bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (day, dimension, value)
);

CREATE INDEX run_calls_run_id ON run_calls(run_id);
CREATE INDEX workout_sessions_start ON workout_sessions(user_id, start);
CREATE INDEX strength_exercises_date ON strength_exercises(user_id, date);
CREATE INDEX strength_exercises_canonical ON strength_exercises(user_id, canonical_id);
CREATE INDEX strength_sets_user ON strength_sets(user_id);
CREATE INDEX drive_exports_user ON drive_exports(user_id, kind);
CREATE INDEX ingest_log_received ON ingest_log(user_id, route, received_at);
CREATE INDEX prompt_section_versions_user ON prompt_section_versions(user_id, section_id);
CREATE INDEX advisor_notes_created ON advisor_notes(user_id, created_at);
CREATE INDEX program_blocks_user ON program_blocks(user_id, start_date);
CREATE INDEX log_sessions_block ON log_sessions(block_id);
CREATE UNIQUE INDEX medication_periods_one_open ON medication_periods(medication_id) WHERE stopped_on IS NULL;
CREATE INDEX medication_periods_started ON medication_periods(user_id, started_on);
CREATE INDEX medication_doses_user ON medication_doses(user_id, date);
CREATE INDEX lab_results_drawn_on ON lab_results(user_id, drawn_on);
CREATE INDEX runs_user ON runs(user_id, name, started_at);
CREATE INDEX users_ingest_token ON users(ingest_token_hash);
CREATE INDEX feedback_user ON feedback(user_id, created_at);
